class ClassicalGnbBipCollectorConfigurator:
    def add_bip(self, ne_log_name, ne_log_configuration):
        webservice = self.tl_config_information_provider.get_web_service(self.ne_id)

        bip_collector_configuration = {
            'name': f"{ne_log_name}",
            'type': "interface_l1l2bip",
            'webservice': webservice
        }

        for parameter_name, parameter_value in ne_log_configuration.items():
            if parameter_name in [
                'interface',
                'nr_cell_dns',
                'parallel_mirroring',
                'timeout'
            ] and parameter_value is not None:
                bip_collector_configuration[parameter_name] = parameter_value

        self._collector_configuration_data.append(bip_collector_configuration)

        self._collector_configuration_data.add_mapping_entry(
            log_type='bip',
            network_element=f'{self.ne_type}_{self.ne_id}',
            collector_configuration=bip_collector_configuration)
